select s.schedule_id, s.offering_id, s.classroom_id, s.week_day, s.start_period, s.end_period, s.start_week, s.end_week, s.schedule_type, s.status, s.del_flag, s.create_by, s.create_time, s.update_by, s.update_time, s.remark, cl.course_name as course_name, t.teacher_name as teacher_name, cr.classroom_name as classroom_name, b.building_name as building_name, o.max_students as max_students, o.teacher_id as teacher_id, o.semester_id as semester_id from tpm_schedule s inner join tpm_course_offering o on s.offering_id = o.offering_id left join tpm_course_library cl on o.course_id = cl.course_id left join brm_teacher t on o.teacher_id = t.teacher_id left join brm_classroom cr on s.classroom_id = cr.classroom_id left join brm_building b on cr.building_id = b.building_id
s.del_flag = '0' and o.del_flag = '0' and s.offering_id = #{offeringId} and s.classroom_id = #{classroomId} and s.week_day = #{weekDay} and o.semester_id = #{semesterId} and s.schedule_type = #{scheduleType} and s.status = #{status}
order by s.week_day, s.start_period

select s.schedule_id, s.offering_id, s.classroom_id, s.week_day, s.start_period, s.end_period, s.start_week, s.end_week, s.schedule_type, s.status, s.create_time, s.remark, cl.course_name as course_name, t.teacher_name as teacher_name, cr.classroom_name as classroom_name, b.building_name as building_name, o.max_students as max_students, o.teacher_id as teacher_id, o.semester_id as semester_id from tpm_selection_enrollment e inner join tpm_course_offering o on e.course_offering_id = o.offering_id inner join tpm_schedule s on s.offering_id = o.offering_id left join tpm_course_library cl on o.course_id = cl.course_id left join brm_teacher t on o.teacher_id = t.teacher_id left join brm_classroom cr on s.classroom_id = cr.classroom_id left join brm_building b on cr.building_id = b.building_id
e.del_flag = '0' and o.del_flag = '0' and s.del_flag = '0' and e.result_status = '1' and s.status = '0' and e.student_id = #{studentId} and o.semester_id = #{semesterId}
order by s.week_day, s.start_period

